 definitions += [dict(shared,id='Q2_JOINT_UP_BREADTH',formula='count(capex_delta>0 & ocf_delta>0 & profit_delta>0)/common known companies',unit='fraction',direction='Operating co-occurrence; not quality or price ranking',source='outputs/r248/industry_diagnostic.parquet'),dict(shared,id='Q2_CAPEX_COHERENCE',formula='(count(ocf_delta>0 & profit_delta>0 & capex_delta>0)-count(ocf_delta<0 & profit_delta<0 & capex_delta>0))/count(capex_delta>0)',unit='signed fraction',direction='Conditional operating coherence; capex-up subset differs across quarters, not causal',source='outputs/r248/industry_diagnostic.parquet')]
