 js(out/'research_entry.json',dict(version='R250',scope='capital_accounting family diagnostic extension, original16-family registry unchanged',routes=routes,new_models=0,adoption=False,production_enabled=False,default_release_unchanged='R183',predictive_increment='not_testable_under_original_history_gate',whole_goal_complete=False))
 inputs=[source,base,ROOT/'outputs/r195/market_regimes.parquet',ROOT/'outputs/r195/experiment_registry.json',ROOT/'outputs/r183/release.json',ROOT/'protocols/r250.json',Path(__file__),ROOT/'src/regime_capital_r206.py',ROOT/'src/regime_core_r196.py']+[ROOT/x['path'] for x in routes.values() if not x['path'].startswith('outputs/r250/')]
